// Rayon + sous-thème du jour — mêmes rotations que MINEA-SPY (dupliquer par rayon)
const RAYON = 'TELEPHONIE';
const CATEGORIES = ['phones & electronics', 'electronics & accessories', 'electronics', 'computers & office']; // filtrage local
const ROTATION = [
  { theme: 'ecrans-externes-accessoires', kw: ['portable monitor', 'usb-c hub'] },
  { theme: 'smartphones',                 kw: ['smartphone', 'refurbished phone'] },
  { theme: 'chargeurs-cables-batteries',  kw: ['charger', 'power bank', 'magnetic cable'] },
  { theme: 'audio',                       kw: ['earbuds', 'bluetooth headphones', 'speaker'] },
  { theme: 'tablettes',                   kw: ['tablet', 'kids tablet', 'stylus'] },
  { theme: 'coques-protections-gadgets',  kw: ['phone case', 'screen protector', 'car phone holder'] },
  { theme: 'objets-connectes',            kw: ['smartwatch', 'gps tracker', 'smart ring'] },
];
const now = new Date(); const pad = n => String(n).padStart(2, '0');
const d = x => `${pad(x.getDate())}-${pad(x.getMonth() + 1)}-${String(x.getFullYear()).slice(2)}`;
const st = ROTATION[now.getDay()];
// domaines gagnants du jour fournis par MINEA-SPY (croisement des sources)
const fs = require('fs'); const path = require('path');
const dir = $env.MARKET_ANALYSES_DIR || './MARKET-ANALYSES';
let domains = [];
try {
  const m = JSON.parse(fs.readFileSync(path.join(dir, `${RAYON}-${d(now)}-MINEA.json`), 'utf8'));
  domains = [...new Set((m.ads || []).filter(a => a.gagnant || a.signal === 'breakout').map(a => { try { return new URL(a.url_produit).hostname.replace(/^www\./, ''); } catch { return null; } }).filter(Boolean))];
} catch (e) {}
return [{ json: { rayon: RAYON, categories: CATEGORIES, sous_theme: st.theme, keywords: st.kw, competitorDomains: domains,
  date_run: d(now), date_prev: d(new Date(now.getTime() - 86400000)) } }];

const SCRIPT = "// DROPSHIP-SPY — script Browserless (/function, Puppeteer)        vérifié sur app.dropship.io le 04-10-2026
//
// PRINCIPE : l'application charge ses données via api.dropship.io en JSON clair (les recherches filtrées partent
// chiffrées → impossible d'appeler l'API directement). Le script visite chaque module avec votre session et
// INTERCEPTE les réponses JSON. Aucune dépendance au design pour les données.
//
// CRÉDITS : 1 crédit = 1 résultat affiché (constaté : 1 page de 50 créateurs = 50 crédits). Les crédits sont MENSUELS.
// Le script calcule chaque jour un budget = (crédits restants − réserve) / jours avant renouvellement / rayons du jour,
// et s'arrête dès qu'il est atteint. Il s'adapte donc tout seul au plan, au jour du mois et au nombre de rayons.

const PLANS = {          // relevé sur /setting/plan le 04-10-2026 (crédits / mois)
  trial:    { product_library: 500,   shop_library: 250,   ad_library: 500,   advertiser_library: 250,   creator_library: 200,
              competitor_per_day: 20,  track_shops: 3,  track_products: 3,   track_advertisers: 3,  drops_week: 20, ai_search: 0 },
  basic:    { product_library: 10000, shop_library: 5000,  ad_library: 10000, advertiser_library: 5000,  creator_library: 3000,
              competitor_per_day: 20,  track_shops: 10, track_products: 25,  track_advertisers: 10, drops_week: 20, ai_search: 100 },
  standard: { product_library: 25000, shop_library: 12500, ad_library: 25000, advertiser_library: 12500, creator_library: 6000,
              competitor_per_day: Infinity, track_shops: 25, track_products: 50, track_advertisers: 25, drops_week: 30, ai_search: 200 },
  premium:  { product_library: 50000, shop_library: 25000, ad_library: 50000, advertiser_library: 25000, creator_library: 10000,
              competitor_per_day: Infinity, track_shops: 50, track_products: 100, track_advertisers: 50, drops_week: 40, ai_search: 400 },
};
const PAGE_SIZE = 50;

// Entrée context = { cookies, plan:"trial|basic|standard|premium", keywords:[], competitorDomains:[],
//                    rayonsToday: 1, renewalDay: 4, creditReserve: 0.05, competitorShare: 1, pause:[ms,ms] }
export default async function ({ page, context }) {
  const APP = "https://app.dropship.io";
  const planName = PLANS[context.plan] ? context.plan : "trial";
  const P = PLANS[planName];
  const rayons = Math.max(1, context.rayonsToday || 1);
  const reservePct = context.creditReserve ?? 0.05;            // 5 % du quota mensuel jamais dépensés
  const [pMin, pMax] = context.pause || [2500, 6000];
  const wait = () => new Promise(r => setTimeout(r, pMin + Math.random() * (pMax - pMin)));
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const warnings = [], captures = [], credits = {}, spent = {}, budget = {};
  let current = null;

  // jours restants avant renouvellement (trial : 7 jours fixes)
  const today = new Date();
  const renewal = new Date(today.getFullYear(), today.getMonth(), context.renewalDay || 1);
  if (renewal <= today) renewal.setMonth(renewal.getMonth() + 1);
  const daysLeft = planName === "trial" ? Math.max(1, context.trialDaysLeft || 7) : Math.max(1, Math.ceil((renewal - today) / 86400000));

  const computeBudget = (m) => {
    const left = credits[m]?.left ?? P[m];
    const usable = Math.max(0, left - Math.ceil(P[m] * reservePct));
    budget[m] = Math.floor(usable / daysLeft / rayons);
    return budget[m];
  };
  const pagesAllowed = (m) => Math.floor((budget[m] ?? computeBudget(m)) / PAGE_SIZE);

  if (Array.isArray(context.cookies) && context.cookies.length) await page.setCookie(...context.cookies);
  await page.setViewport({ width: 1440, height: 900 });

  page.on("response", async (res) => {
    try {
      const u = new URL(res.url());
      if (u.hostname !== "api.dropship.io" || !current) return;
      if (!(res.headers()["content-type"] || "").includes("json")) return;
      const body = await res.json();
      if (/filter_presets/.test(u.pathname) && body && "credits_left" in body) {
        credits[current] = { left: body.credits_left, total: body.total_credits, attempts: body.attempts_left }; return;
      }
      if (/choice_filters|auto-ds|user\/stores/.test(u.pathname)) return;
      if (body && (Array.isArray(body.results) || Array.isArray(body))) {
        const n = Array.isArray(body) ? body.length : body.results.length;
        captures.push({ module: current, api: u.pathname, count: body.count ?? null, body });
        spent[current] = (spent[current] || 0) + n;
        if (body.credits_left != null) credits[current] = { ...(credits[current] || {}), left: body.credits_left };
        if (body.attempts_left != null) credits[current] = { ...(credits[current] || {}), attempts: body.attempts_left };
      }
    } catch (_) {}
  });

  const clickText = (label) => page.evaluate((label) => {
    const el = [...document.querySelectorAll("button,[role=tab],[role=button],a,span,div")]
      .find(e => e.children.length <= 3 && e.innerText && e.innerText.trim() === label);
    if (el) { el.click(); return true; } return false;
  }, label);

  const nextPage = () => page.evaluate(() => {                 // bouton "page suivante" (› / > / aria-label next)
    const b = [...document.querySelectorAll("button, li, a")].find(e =>
      /next/i.test(e.getAttribute("aria-label") || e.getAttribute("title") || e.className || "") && !e.disabled && !/disabled/.test(e.className || ""));
    if (b) { b.click(); return true; } return false;
  });

  const search = async (kw) => {
    const input = await page.$('input[placeholder*="earch" i], input[placeholder*="nclude" i], input[type="text"]');
    if (!input) { warnings.push(`${current} : champ de recherche introuvable`); return false; }
    await input.click({ clickCount: 3 }); await input.type(kw, { delay: 70 });
    await page.keyboard.press("Enter"); await sleep(6000); return true;
  };

  // parcourt les pages tant que le budget du module le permet
  const paginate = async (m) => {
    let pages = 1;
    while (pages < pagesAllowed(m) && (spent[m] || 0) + PAGE_SIZE <= budget[m]) {
      if (!(await nextPage())) break;
      await sleep(5000); pages++;
    }
  };

  const canSearch = (m) => {
    if (credits[m]?.attempts != null && credits[m].attempts <= 0) { warnings.push(`${m} : plus de recherches aujourd'hui`); return false; }
    if (m in P && typeof P[m] === "number" && P[m] > 0 && (spent[m] || 0) + PAGE_SIZE > (budget[m] ?? computeBudget(m))) {
      warnings.push(`${m} : budget du jour atteint (${budget[m]} crédits)`); return false; }
    return true;
  };

  const visit = async (m, path, actions) => {
    current = m;
    await page.goto(APP + path, { waitUntil: "networkidle2", timeout: 90000 });
    await sleep(4000);
    const p = new URL(page.url()).pathname;
    if (/login|sign-in|onboarding/.test(p)) { warnings.push(`${m} : redirigé vers ${p} (session expirée / essai terminé)`); current = null; return; }
    if (await page.evaluate(() => /captcha|verify you are human/i.test(document.body.innerText))) throw new Error("CAPTCHA_OR_BOT_CHECK");
    if (m in P) computeBudget(m);
    if (actions) { try { await actions(); } catch (e) { warnings.push(`${m} : ${String(e).slice(0, 120)}`); } }
    await wait(); current = null;
  };

  // intensité selon le plan
  const kwAll = context.keywords || [];
  const kws = { trial: kwAll.slice(0, 1), basic: kwAll.slice(0, 2), standard: kwAll, premium: kwAll }[planName];
  const domLimit = { trial: 3, basic: Math.floor(20 * (context.competitorShare ?? 1) / rayons) || 1, standard: 15, premium: 25 }[planName];
  const doms = (context.competitorDomains || []).slice(0, domLimit);
  const adPresets = { trial: ["Weekly winners"], basic: ["Weekly winners"], standard: ["Weekly winners", "New Winning products"],
                      premium: ["Weekly winners", "New Winning products", "Evergreen Winners"] }[planName];

  try {
    // 1. Suivis + Portfolio : sans crédit
    await visit("sales_tracker", "/products/sales-tracker");
    await visit("advertiser_tracker", "/ads/advertiser-tracker");
    await visit("portfolio", "/portfolio");

    // 2. Ad Library (Facebook EU)
    await visit("ad_library", "/ads/ad-library", async () => {
      for (const pr of adPresets) { if (!canSearch("ad_library")) break; await clickText(pr); await sleep(6000); await paginate("ad_library"); }
      for (const k of kws) { if (!canSearch("ad_library")) break; await search(k); await paginate("ad_library"); }
    });

    // 3. Product Library (TikTok Shop)
    await visit("product_library", "/products/product-library", async () => {
      for (const k of kws) { if (!canSearch("product_library")) break; await search(k); await paginate("product_library"); }
    });

    // 4. Competitor Research (Shopify) — croisement Minea
    await visit("competitor_research", "/competitor-research", async () => {
      for (const q of [...kws.slice(0, 1), ...doms]) { if (!canSearch("competitor_research")) break; await search(q); }
    });

    // 5. Advertiser Library (dès Basic)
    if (planName !== "trial") await visit("advertiser_library", "/ads/advertiser-library", async () => {
      for (const k of kws) { if (!canSearch("advertiser_library")) break; await search(k); await paginate("advertiser_library"); }
    });

    // 6. Shop Library + Creator Library (Standard / Premium)
    if (planName === "standard" || planName === "premium") {
      await visit("shop_library", "/products/shop-library", async () => { if (canSearch("shop_library")) await paginate("shop_library"); });
      await visit("creator_library", "/products/creator-library", async () => {
        if (!canSearch("creator_library")) return;
        await clickText("Fast-growing creators"); await sleep(6000); await paginate("creator_library");
      });
    }

    return { data: { ok: true, plan: planName, limits: P, daysLeft, rayonsToday: rayons, budget, spent, credits, captures, warnings,
                     scrapedAt: new Date().toISOString() }, type: "application/json" };
  } catch (e) {
    return { data: { ok: false, error: String(e).slice(0, 300), plan: planName, budget, spent, credits, captures, warnings }, type: "application/json" };
  }
}
";
let cookies = []; try { cookies = JSON.parse($env.DROPSHIP_COOKIES || '[]'); } catch (e) {}
const c = $input.first().json;
return [{ json: { code: SCRIPT, context: { cookies, plan: $env.DROPSHIP_PLAN || 'trial', keywords: c.keywords, competitorDomains: c.competitorDomains,
  rayonsToday: Number($env.DROPSHIP_RAYONS_PAR_JOUR || 1),      // nb de rayons qui partagent le quota ce jour-là
  renewalDay: Number($env.DROPSHIP_RENEWAL_DAY || 1),           // jour du mois de renouvellement de l'abonnement
  trialDaysLeft: Number($env.DROPSHIP_TRIAL_DAYS_LEFT || 7),
  creditReserve: Number($env.DROPSHIP_CREDIT_RESERVE_PCT || 0.05), pause: [2500, 6000] } } }];

// Normalisation par module + filtrage rayon + scoring + alertes + croisement Minea + archivage
const fs = require('fs'); const path = require('path');
const cfg = $('Config du jour').first().json;
const raw = $input.first().json;
if (!raw.ok) throw new Error('Dropship : ' + (raw.error || 'échec'));
const dir = $env.MARKET_ANALYSES_DIR || './MARKET-ANALYSES'; fs.mkdirSync(dir, { recursive: true });

const inRayon = (...cats) => cats.filter(Boolean).some(c => cfg.categories.some(k => String(c).toLowerCase().includes(k)));
const kwHit = (t) => cfg.keywords.some(k => String(t || '').toLowerCase().includes(k.toLowerCase().split(' ')[0]));
const media = (o) => { const out = []; JSON.stringify(o || {}, (k, v) => { if (typeof v === 'string' && /^https?:\/\/.+\.(jpe?g|png|webp|mp4)(\?|$)/i.test(v)) out.push(v); return v; }); return [...new Set(out)].slice(0, 6); };
const host = (u) => { try { return new URL(u.startsWith('http') ? u : 'https://' + u).hostname.replace(/^www\./, ''); } catch { return null; } };

const N = { tiktok_products: [], tiktok_shops: [], creators: [], fb_ads: [], advertisers: [], shopify_products: [], tracked_shops: [], tracked_advertisers: [], portfolio: [] };
for (const c of raw.captures || []) {
  const rows = Array.isArray(c.body) ? c.body : (c.body.results || []);
  const a = c.api;
  for (const r of rows) {
    if (/tiktok_shops\/search/.test(a)) N.tiktok_products.push({ id: r.product_id, titre: r.title, url: r.url, image: r.image,
      prix_usd: r.usd_price, ventes_30j: r.monthly_sales, ca_30j_usd: r.monthly_revenue, croissance_30j: r.revenue_growth_rate_30d,
      categorie: r.category_name, pays: r.country?.code, lance_le: r.publish_date, note: r.rating, avis: r.review_count, videos: r.videos_count,
      boutique: r.shop?.name, livraison_gratuite: r.shipping?.[0]?.is_free ?? null, delai_jours: r.shipping?.[0]?.delivery_days_duration ?? null });
    else if (/tiktok_shops\/shops\/search/.test(a)) N.tiktok_shops.push({ id: r.seller_id, nom: r.name, url: r.url, ca_30j_usd: r.monthly_revenue,
      ventes_30j: r.monthly_sales, croissance_30j: r.revenue_growth_rate_30d, nb_produits: r.products_count, prix_moyen: r.avg_product_price,
      pays: r.country?.code, categories: r.categories, top_produits: (r.top_products || []).map(p => ({ titre: p.title, url: p.url, ca_30j_usd: p.monthly_revenue, ventes_30j: p.monthly_sales })) });
    else if (/tiktok_creators\/search/.test(a)) { const m = r.monthly_creator_metrics || {}; N.creators.push({ id: r.creator_id, nom: r.name, username: r.username,
      ca_30j_usd: m.revenue, ventes_30j: m.sales, croissance: m.revenue_growth_rate, vues_30j: m.video_views, engagement: m.engagement_rate,
      abonnes: r.creator_metrics?.follower_count, nb_produits: r.products_count,
      top_videos: (r.top_viewed_videos || []).map(v => ({ id: v.video_id, cover: v.video_cover_image_url, description: (v.video_description || '').slice(0, 200) })) }); }
    else if (/ad_library\/ads\/search/.test(a)) { const s = r.snapshot || {}; N.fb_ads.push({ id: r.collation_id, annonceur: r.advertiser?.page_name,
      annonces_actives_page: r.advertiser?.active_ads_count, depense_usd: r.ad_spend, adsets: r.ad_sets_count, reach: r.total_reaches_count,
      format: r.creative_type, cree_le: r.created_at, vue_le: r.last_seen_date, active: r.is_active, eu: r.is_eu_targeted, langue: r.language,
      domaine: (r.domain_fld || [])[0] || host(s.link_url || ''), lien: s.link_url, titre: s.title, texte: (s.body?.text || s.body || '').toString().slice(0, 400),
      cta: s.cta_text, creatives: media(s) }); }
    else if (/advertisers_library\/search/.test(a)) N.advertisers.push({ id: r.id, nom: r.name, categorie: r.page_category, domaines: r.domains,
      depense_30j_usd: r.monthly_spend, reach_30j: r.monthly_reach, croissance_depense: r.ad_spend_growth_rate_30d, depense_totale_usd: r.total_ads_spend,
      adsets_eu_actifs: r.total_eu_active_adsets_count, pays: (r.targeted_countries || []).map(x => x.code), derniere_pub: r.last_ad_date, pct_non_shopify: r.percent_non_shopify });
    else if (/product_database\/.*competitors\/search/.test(a)) { const st = r.store || {}; const dom = st.custom_domain || st.best_ranked_domain || st.original_domain;
      N.shopify_products.push({ id: r.id, titre: r.title, prix_usd: r.usd_price, categorie: r.category, sous_categorie: r.subcategory_short_name,
        cree_le: r.created_at, image: r.main_image, domaine: dom, boutique: st.title, nb_produits_boutique: st.products_count,
        url: dom && r.handle ? `https://${dom}/products/${r.handle}` : null }); }
    else if (/collections\/shops\/entities/.test(a)) N.tracked_shops.push(r.full_info);
    else if (/collections\/advertisers\/entities/.test(a)) N.tracked_advertisers.push(r.full_info);
    else if (/\/portfolio\//.test(a)) N.portfolio.push({ mois: r.month, annee: r.year, drops: (r.drops || []).map(x => ({ id: x.drop_id, date: x.drop_date, taille: x.drop_plan_size, a_venir: x.comming_up })) });
  }
}
// dédoublonnage par id
for (const k of Object.keys(N)) { const seen = new Set(); N[k] = N[k].filter(x => { const id = x?.id ?? JSON.stringify(x).slice(0, 80); if (seen.has(id)) return false; seen.add(id); return true; }); }

// filtrage rayon (catégorie OU mot-clé du sous-thème)
const R = {
  tiktok_products: N.tiktok_products.filter(p => inRayon(p.categorie) || kwHit(p.titre)),
  fb_ads: N.fb_ads.filter(a => kwHit(a.titre) || kwHit(a.texte) || cfg.competitorDomains.includes(a.domaine)),
  shopify_products: N.shopify_products.filter(p => inRayon(p.categorie, p.sous_categorie) || kwHit(p.titre) || cfg.competitorDomains.includes(p.domaine)),
  advertisers: N.advertisers.filter(a => inRayon(a.categorie) || (a.domaines || []).some(d => cfg.competitorDomains.includes(host(d)))),
};

// scores /20
for (const p of R.tiktok_products) p.score_ventes = Math.min(20, Math.round(Math.min(10, (p.ca_30j_usd || 0) / 5000) + Math.min(6, Math.max(0, (p.croissance_30j || 0) * 10)) + (p.videos > 0 ? 2 : 0) + ((p.note || 0) >= 4.5 ? 2 : 0)));
for (const a of R.fb_ads) a.score_pub = Math.min(20, Math.round(Math.min(10, (a.depense_usd || 0) / 2000) + Math.min(6, (a.adsets || 0) * 1.5) + (a.active ? 2 : 0) + (a.eu ? 2 : 0)));

// historique J-1 + alertes
const prevFile = path.join(dir, `${cfg.rayon}-${cfg.date_prev}-DROPSHIP.json`);
let prev = {}; try { prev = JSON.parse(fs.readFileSync(prevFile, 'utf8')); } catch (e) {}
const byId = (arr) => Object.fromEntries((arr || []).map(x => [x.id, x]));
const alerts = [];
const pp = byId(prev.rayon?.tiktok_products);
for (const p of R.tiktok_products) { const o = pp[p.id];
  if (o && o.ventes_30j && p.ventes_30j >= o.ventes_30j * 1.5) alerts.push({ type: 'BREAKOUT', source: 'tiktok', titre: p.titre, de: o.ventes_30j, a: p.ventes_30j, url: p.url });
  if (o && o.prix_usd && p.prix_usd < o.prix_usd * 0.85) alerts.push({ type: 'BAISSE DE PRIX', titre: p.titre, de: o.prix_usd, a: p.prix_usd, url: p.url });
  if ((p.croissance_30j || 0) >= 0.5) alerts.push({ type: 'FORTE CROISSANCE', titre: p.titre, croissance: p.croissance_30j, url: p.url }); }
for (const a of R.fb_ads) if ((a.depense_usd || 0) >= 10000 && a.active) alerts.push({ type: 'GROS BUDGET PUB', annonceur: a.annonceur, depense_usd: a.depense_usd, domaine: a.domaine });
// croisement Minea : même domaine trouvé par les 2 outils
const valid = [...new Set([...R.fb_ads.map(a => a.domaine), ...R.shopify_products.map(p => p.domaine)].filter(d => cfg.competitorDomains.includes(d)))];
for (const d of valid) alerts.push({ type: 'VALIDÉ 2 SOURCES', domaine: d, note: 'gagnant Minea confirmé par dropship.io' });

const out = { source: 'dropship.io', rayon_nom: cfg.rayon, sous_theme: cfg.sous_theme, mots_cles: cfg.keywords, date_run: cfg.date_run,
  plan: raw.plan, limits: raw.limits, budget: raw.budget, spent: raw.spent, credits: raw.credits, warnings: raw.warnings, alerts,
  rayon: R,      // données filtrées sur le rayon (relues au run suivant pour les alertes)
  tout: N,       // tout ce qui a été capturé, toutes catégories
  scrapedAt: raw.scrapedAt };
const file = path.join(dir, `${cfg.rayon}-${cfg.date_run}-DROPSHIP.json`);
fs.writeFileSync(file, JSON.stringify(out, null, 2));
return [{ json: { file, rayon_nom: cfg.rayon, sous_theme: cfg.sous_theme, date_run: cfg.date_run, plan: raw.plan, budget: raw.budget, spent: raw.spent, credits: raw.credits, warnings: raw.warnings, alerts,
  top: { tiktok_products: [...R.tiktok_products].sort((a, b) => (b.score_ventes || 0) - (a.score_ventes || 0)).slice(0, 20),
         fb_ads: [...R.fb_ads].sort((a, b) => (b.score_pub || 0) - (a.score_pub || 0)).slice(0, 15),
         shopify_products: R.shopify_products.slice(0, 20), advertisers: R.advertisers.slice(0, 10),
         creators: N.creators.slice(0, 10), tracked_shops: N.tracked_shops, portfolio: N.portfolio.slice(0, 1) } } }];

