const fs = require('fs'); const path = require('path');
const d = $('Parse, score & alertes').first().json;
const text = ($input.first().json.content || []).map(b => b.text || '').join('\n');
const file = path.join($env.MARKET_ANALYSES_DIR || './MARKET-ANALYSES', `${d.rayon_nom}-${d.date_run}-DROPSHIP.md`);
fs.writeFileSync(file, `# ${d.rayon_nom} — ${d.sous_theme} — ${d.date_run} — Ventes & concurrence (dropship.io)\n\n${text}\n`);
